// Reference for an exclusive band of contiguous integer IDs and plain immutable records.
function makeCells(host, records, start, end) {
  const doc = host.ownerDocument;
  const fragment = doc.createDocumentFragment();
  for (let i = start; i < end; i++) {
    const record = records[i];
    const cell = doc.createElement('div');
    cell.className = 'cell';
    cell.setAttribute('data-id', record.id);
    cell.textContent = record.id + ' · ' + record.score;
    fragment.appendChild(cell);
  }
  return fragment;
}

function replaceAll(host, records) {
  host.replaceChildren(makeCells(host, records, 0, records.length));
}

function addEdge(host, records, start, end, prepend) {
  host.insertBefore(makeCells(host, records, start, end), prepend ? host.firstChild : null);
}

function removeSpan(host, start, end) {
  if (start === end) return;
  const range = host.ownerDocument.createRange();
  range.setStart(host, start);
  range.setEnd(host, end);
  range.deleteContents();
}

export function mountScaleBand(host, initialRecords) {
  let previous = [];
  function replace(next) {
    const oldFirst = previous[0]?.id ?? 0;
    const oldEnd = oldFirst + previous.length;
    const first = next[0]?.id ?? 0;
    const end = first + next.length;
    const overlapStart = Math.max(oldFirst, first);
    const overlapEnd = Math.min(oldEnd, end);

    if (overlapStart >= overlapEnd) {
      replaceAll(host, next);
    } else {
      for (let id = overlapStart; id < overlapEnd; id++) {
        const record = next[id - first];
        if (previous[id - oldFirst] !== record) {
          host.children[id - oldFirst].firstChild.data = record.id + ' · ' + record.score;
        }
      }
      // Remove the suffix first so the old prefix indices stay valid.
      removeSpan(host, overlapEnd - oldFirst, previous.length);
      removeSpan(host, 0, overlapStart - oldFirst);
      if (first < overlapStart) addEdge(host, next, 0, overlapStart - first, true);
      if (overlapEnd < end) addEdge(host, next, overlapEnd - first, next.length, false);
    }
    previous = next;
  }
  replace(initialRecords);
  return {
    replace,
    dispose() {
      previous = [];
      host.replaceChildren();
    },
  };
}

