// Reference only for numeric IDs/scores in this grid's plain immutable records.
function cellMarkup(records, start, end) {
  let markup = '';
  for (let i = start; i < end; i++) {
    const record = records[i];
    markup += '<div class="cell" data-id="' + record.id + '">' + record.id + ' · ' + record.score + '</div>';
  }
  return markup;
}

function replaceAll(host, records) {
  host.innerHTML = cellMarkup(records, 0, records.length);
}

function addEdge(host, records, start, end, prepend) {
  host.insertAdjacentHTML(prepend ? 'afterbegin' : 'beforeend', cellMarkup(records, start, end));
}

