// Fixture reference for immutable records in a contiguous, ascending ID window.
// Div and Text belong to slots. Keys which stay in the window keep their slot.
function label(record) {
  return record.id + ' · ' + record.score;
}

function createCell(record) {
  const element = document.createElement('div');
  element.className = 'cell';
  element.setAttribute('data-id', record.id);
  const text = document.createTextNode(label(record));
  element.appendChild(text);
  return {element, text};
}

function rebind(cell, record) {
  cell.element.setAttribute('data-id', record.id);
  cell.text.data = label(record);
}

export function mountScaleBand(host, initialRecords) {
  let records = initialRecords;
  let cells = records.map(createCell);
  const initial = document.createDocumentFragment();
  for (const cell of cells) initial.appendChild(cell.element);
  host.appendChild(initial);

  function replace(next) {
    const oldFirst = records[0]?.id ?? 0;
    const newFirst = next[0]?.id ?? 0;
    const sharedStart = Math.max(oldFirst, newFirst);
    const sharedEnd = Math.min(oldFirst + records.length, newFirst + next.length);

    if (oldFirst === newFirst && records.length === next.length) {
      for (let i = 0; i < next.length; i++) {
        if (records[i] !== next[i]) cells[i].text.data = label(next[i]);
      }
    } else if (sharedEnd <= sharedStart) {
      // A full jump can rebind every surviving slot in place, without a move.
      const keep = Math.min(cells.length, next.length);
      for (let i = 0; i < keep; i++) rebind(cells[i], next[i]);
      while (cells.length > next.length) cells.pop().element.remove();
      for (let i = keep; i < next.length; i++) {
        const cell = createCell(next[i]);
        host.appendChild(cell.element);
        cells.push(cell);
      }
    } else {
      const oldStart = sharedStart - oldFirst;
      const newStart = sharedStart - newFirst;
      const length = sharedEnd - sharedStart;
      const available = cells.slice(0, oldStart).concat(cells.slice(oldStart + length));
      const nextCells = new Array(next.length);
      for (let i = 0; i < length; i++) {
        const cell = cells[oldStart + i];
        const record = next[newStart + i];
        if (records[oldStart + i] !== record) cell.text.data = label(record);
        nextCells[newStart + i] = cell;
      }
      const anchor = cells[oldStart].element;
      function enter(i, before) {
        let cell = available.pop();
        if (cell) rebind(cell, next[i]);
        else cell = createCell(next[i]);
        host.insertBefore(cell.element, before);
        nextCells[i] = cell;
      }
      for (let i = 0; i < newStart; i++) enter(i, anchor);
      for (let i = newStart + length; i < next.length; i++) enter(i, null);
      for (const cell of available) cell.element.remove();
      cells = nextCells;
    }
    records = next;
  }

  function dispose() {
    for (const cell of cells) cell.element.remove();
    records = [];
    cells = [];
  }
  return {replace, dispose};
}

