import {batch, effect, signal} from 'saba-dom';
export {signal};

function prepare(doc, item) {
  const record = signal(item);
  const id = record().id;
  const node = doc.createElement('div');
  node.className = 'cell';
  node.setAttribute('data-id', id);
  let text;
  const stop = effect(() => {
    const value = id + ' · ' + record().score;
    if (!text) {
      text = doc.createTextNode(value);
      node.appendChild(text);
    } else if (text.data !== value) {
      text.data = value;
    }
  });
  return {record, node, stop, fresh:true};
}

// The host exclusively contains this fixed tag, class, key attribute and text binding.
// Rows may have sparse, mixed-type keys, change order, or read other signals.
export function mountScaleBand(host, initialRecords) {
  const doc = host.ownerDocument;
  let rows = new Map();
  function replace(records) {
    const next = new Map();
    const ordered = new Array(records.length);
    const keys = new Array(records.length);
    for (let i = 0; i < records.length; i++) {
      const key = records[i].id;
      if (typeof key !== 'string' && !Number.isFinite(key)) throw new TypeError('Invalid key');
      if (next.has(key)) throw new Error('Duplicate key');
      const row = rows.get(key);
      next.set(key, row);
      ordered[i] = row;
      keys[i] = key;
    }
    const added = [];
    try {
      for (let i = 0; i < ordered.length; i++) {
        if (ordered[i]) continue;
        const row = prepare(doc, records[i]);
        added.push(row);
        ordered[i] = row;
        next.set(keys[i], row);
      }
    } catch (error) {
      for (const row of added) row.stop();
      throw error;
    }

    batch(() => {
      if (added.length === ordered.length) {
        const fragment = doc.createDocumentFragment();
        for (const row of added) {
          row.fresh = false;
          fragment.appendChild(row.node);
        }
        for (const row of rows.values()) row.stop();
        host.replaceChildren(fragment);
      } else {
        for (const [key, row] of rows) {
          if (!next.has(key)) {
            row.stop();
            row.node.remove();
          }
        }
        let before = null;
        let i = ordered.length - 1;
        while (i >= 0) {
          const row = ordered[i];
          if (row.fresh) {
            const end = i + 1;
            while (i >= 0 && ordered[i].fresh) i--;
            const fragment = doc.createDocumentFragment();
            for (let j = i + 1; j < end; j++) {
              ordered[j].fresh = false;
              fragment.appendChild(ordered[j].node);
            }
            host.insertBefore(fragment, before);
            before = ordered[i + 1].node;
          } else {
            row.record.set(records[i]);
            if (row.node.nextSibling !== before) {
              if (host.moveBefore) host.moveBefore(row.node, before);
              else host.insertBefore(row.node, before);
            }
            before = row.node;
            i--;
          }
        }
      }
      rows = next;
    });
  }
  replace(initialRecords);
  return {
    replace,
    dispose() {
      for (const row of rows.values()) row.stop();
      rows.clear();
      host.replaceChildren();
    },
  };
}

import {verifyReactiveKeyed} from './reactive-keyed-smoke.mjs';
export function verifyReactiveReference() {
  return verifyReactiveKeyed({mountScaleBand, signal});
}

