// Pass the same module used by the timed visits. No DOM work survives this check.
export function verifyReactiveKeyed({mountScaleBand, signal}) {
  const check = (test, message) => { if (!test) throw Error(message); };
  const host = document.createElement('div');
  document.body.appendChild(host);
  let aReads = 0, bReads = 0, stagedReads = 0;
  const a = signal(5), b = signal(8);
  const first = {id:'a', get score() { aReads++; return a(); }};
  const second = {id:15.5, score:10};
  const band = mountScaleBand(host, [first,second]);
  try {
    const firstNode = host.firstChild, firstText = firstNode.firstChild;
    const secondNode = host.lastChild;
    a.set(6);
    check(firstText.data === 'a · 6', 'Independent signal lost');
    const replaced = {id:'a',get score() { bReads++; return b(); }};
    band.replace([second, {id:-8,score:3}, {id:'arbitrary/key',score:11}, replaced]);
    check(host.children[1].dataset.id === '-8' && host.children[2].dataset.id === 'arbitrary/key' &&
      host.lastChild === firstNode && host.firstChild === secondNode &&
      firstNode.firstChild === firstText && firstText.data === 'a · 8','Key or text identity lost');
    const oldReads = aReads;
    a.set(7);
    check(oldReads === aReads, 'Stale field dependency');
    b.set(9);
    check(firstText.data === 'a · 9', 'Replacement did not subscribe');
    const before = [...host.childNodes];
    const staged = {id:'new',get score() { stagedReads++; return a(); }};
    for (const [records, error] of [
      [[staged,{id:'new',score:1}],'Duplicate key'],
      [[staged,{id:Infinity,score:1}],'Invalid key'],
      [[staged,{id:'bad',get score() { throw Error('bad read'); }}],'bad read'],
    ]) {
      let caught;
      try { band.replace(records); } catch (failure) { caught = failure.message; }
      check(caught === error, 'Wrong validation or staging failure');
      check(host.childNodes.length === before.length && before.every((n,i) => n === host.childNodes[i]),
        'Failure changed committed cells');
    }
    check(stagedReads === 1,'Validation happened after setup');
    a.set(11);
    check(stagedReads === 1,'Staged row leaked its subscription');
    band.replace([second]);
    const oldBReads = bReads;
    b.set(12);
    check(bReads === oldBReads && !firstNode.isConnected && secondNode === host.firstChild,
      'Removal leaked an effect or disconnected a retained row');
    band.replace([first]);
    band.dispose();
    const disposedReads = aReads;
    a.set(14);
    check(aReads === disposedReads && host.childNodes.length === 0,'Disposal leaked an effect');
    return {dynamicDependencies:true, reordered:true, stagedRollback:true, cleanup:true};
  } finally { band.dispose(); host.remove(); }
}
